{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Aprepitant, which shares the same 3,5-bis(trifluoromethyl)phenyl chiral carbinol ether motif as the query, has an absolute oral bioavailability of 67% for the 80 mg capsule in healthy subjects, strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Maraviroc, a CCR5 antagonist with a basic amine and amide-containing scaffold, has an observed absolute oral bioavailability of 23.1% (95% CI 19.2–27.8) in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Odanacatib, a lipophilic CF3-containing amide, has an absolute oral bioavailability of 30% at a 50 mg fasted oral dose in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Silodosin, which contains ether, basic amine, amide, and trifluoromethyl features, has an absolute oral bioavailability of 32.2% in healthy adult men under fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Dutasteride, a lipophilic bis-CF3 anilide, has an absolute oral bioavailability of approximately 60% in humans, supporting high oral bioavailability for structurally related lipophilic amides.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues have human absolute oral bioavailability values of 23–100%, all above the 20% threshold. The query shares key structural features with these high-F drugs, especially the bis-CF3 phenyl ether motif of aprepitant and the basic amine/amide architecture of maraviroc and vicriviroc, so F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule itself.",
    "Potential dose-dependent absorption or transporter effects for the query are not directly characterized.",
    "The exact ionization and permeability profile of the query's spiro lactam/amine system is inferred from analogs rather than measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

